public class InnerUserSettingsBrandingConfigurationFactory(Action<Humidifier.WorkSpacesWeb.UserSettingsTypes.BrandingConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.WorkSpacesWeb.UserSettingsTypes.BrandingConfiguration>
{

    internal InnerUserSettingsImageMetadataFactory FaviconMetadataFactory { get; set; }

    internal InnerUserSettingsImageMetadataFactory WallpaperMetadataFactory { get; set; }

    internal InnerUserSettingsImageMetadataFactory LogoMetadataFactory { get; set; }

    protected override Humidifier.WorkSpacesWeb.UserSettingsTypes.BrandingConfiguration Create()
    {
        var brandingConfigurationResult = CreateBrandingConfiguration();
        factoryAction?.Invoke(brandingConfigurationResult);

        return brandingConfigurationResult;
    }

    private Humidifier.WorkSpacesWeb.UserSettingsTypes.BrandingConfiguration CreateBrandingConfiguration()
    {
        var brandingConfigurationResult = new Humidifier.WorkSpacesWeb.UserSettingsTypes.BrandingConfiguration();

        return brandingConfigurationResult;
    }
    public override void CreateChildren(Humidifier.WorkSpacesWeb.UserSettingsTypes.BrandingConfiguration result)
    {
        base.CreateChildren(result);

        result.FaviconMetadata ??= FaviconMetadataFactory?.Build();
        result.WallpaperMetadata ??= WallpaperMetadataFactory?.Build();
        result.LogoMetadata ??= LogoMetadataFactory?.Build();
    }

} // End Of Class

